def test_process_publication_fault_reopens_complete_or_requires_recovery(
    tmp_path: Path, cold: bool, stage: str
) -> None:
    path = tmp_path / "budget.json"
    if not cold:
        _complete_snapshot(path)
    result = _child(
        path,
        "fault_bootstrap" if cold else "fault_spend",
        stage,
        allow_kill=stage.startswith("kill_"),
    )
    if stage.startswith("kill_"):
        assert result["killed"] is True
    else:
        assert result["exception"] == "OSError", result
    reopened = _child(path, "load")
    if cold and stage in {"file_fsync", "replace_before", "kill_before_replace"}:
        assert not path.exists(), "failed first publication must not leave an empty target"
        assert reopened["exception"] == "FileNotFoundError", reopened
        assert _child(path, "middleware")["exception"] == "BudgetExhaustedError"
    else:
        assert reopened["refused"] is False, reopened
        assert reopened["state"]["limits"]["run"]["max_usd"] == "10"
        if cold:
            assert reopened["state"]["spent"]["run"] == "10"
            assert _child(path, "middleware")["exception"] == "BudgetExhaustedError"
        else:
            expected = (
                "3" if stage in {"file_fsync", "replace_before", "kill_before_replace"} else "4"
            )
            assert reopened["state"]["spent"]["run"] == expected

def test_owned_supervisor_reaps_real_new_session_grandchild(
    owned_tree_dir, ctx, state, mode, finish
):
    tmp_path = owned_tree_dir
    original_flag = _caller_subreaper_flag()
    node = _OwnedProcessTreeNode(tmp_path, finish=finish)
    kwargs = {"retry_policy": RetryPolicy(), "timeout_s": 0.3, "alias": "actual-tree"}
    if finish:
        outcome = (
            execute_with_retry_sync(node, ctx, state, **kwargs)
            if mode == "sync"
            else asyncio.run(execute_with_retry_async(node, ctx, state, **kwargs))
        )
        assert outcome.status == "ok"
    else:

        def invoke():
            if mode == "sync":
                return execute_with_retry_sync(node, ctx, state, **kwargs)
            return asyncio.run(execute_with_retry_async(node, ctx, state, **kwargs))

        with pytest.raises(NodeTimeoutError) as expired:
            invoke()
    _assert_real_tree_reaped(tmp_path)
    if not finish:
        assert expired.value.details["execution_state"] == "owned_processes_reaped"
        assert expired.value.details["cleanup_complete"] is True
    assert _caller_subreaper_flag() == original_flag
